sp_widget.client_script:
/*
  CLM – Non-Trade Approval Requests (Zonal: ZHM / ZCH) – Client Script  v1.0
  - This widget is always Non-Trade ('non_trade'). Picking another business reverts the dropdown and
    broadcasts 'clm.business.changed' with the DASHBOARD key (trade / nonTrade / key).
  - Segment, Zone, Region, Depot = multiselects; Segment / Zone lists come from the server
    (NT roles + approval-matrix zones); Region / Depot follow the selected zones.
  - First load: server returns a light placeholder (data.initialLoad); client calls applyFilters().
*/
function widgetcontroller($scope, $rootScope, $timeout) {
  var c = this;

  var NT_BUSINESS = 'non_trade';
  var DEFAULT_BUSINESS = NT_BUSINESS;
  var HOST_KEY = { trade: 'trade', non_trade: 'nonTrade', key: 'key' };
  var FALLBACK_BUSINESS_OPTIONS = [{ value: 'non_trade', label: 'Non-Trade', enabled: true }];

  c.filters = {
    business: c.data.selectedBusiness || DEFAULT_BUSINESS,
    segments: [], zones: [], regions: [], depots: [],
    status: '',
    period: c.data.selectedPeriod || 'latest',
    search: ''
  };

  c.rowsPerPageOptions = [10, 15, 20, 50, 100];
  c.pagination = { currentPage: 1, rowsPerPage: 10 };
  c.hoverIndex = -1;
  c.showTooltip = false;
  c.paginatedRequests = [];
  c.kpiFilter = '';
  c.kpiLabels = { pending: 'Pending', approved: 'Approved', rejected: 'Rejected', deviated: 'Deviated' };

  c.seriesDefs = [
    { key: 'pending',  label: 'Pending' },
    { key: 'approved', label: 'Approved' },
    { key: 'rejected', label: 'Rejected' },
    { key: 'total',    label: 'Total' }
  ];

  c.closeAllDropdowns = function() {
      c.segmentDropdownOpen = false; c.zoneDropdownOpen = false;
      c.regionDropdownOpen = false;  c.depotDropdownOpen = false;
  };

  // ===================== BUSINESS =====================
  c.getBusinessOptions = function() {
      return (c.data && c.data.businessOptions && c.data.businessOptions.length) ? c.data.businessOptions : FALLBACK_BUSINESS_OPTIONS;
  };
  c.isBusinessEnabled = function(value) {
      return c.getBusinessOptions().some(function(b) { return b.value === value && b.enabled; });
  };
  c._lastBusiness = c.filters.business;

  c.onBusinessChange = function() {
      var value = c.filters.business;
      if (!c.isBusinessEnabled(value)) { c.filters.business = c._lastBusiness || DEFAULT_BUSINESS; return; }
      if (value === c._lastBusiness) return;

      if (value !== NT_BUSINESS) {
          c.filters.business = c._lastBusiness;
          $rootScope.$broadcast('clm.business.changed', { business: HOST_KEY[value] || value, from: 'nonTrade' });
          return;
      }
      c._lastBusiness = value;
      c.filters.zones = []; c.filters.regions = []; c.filters.depots = [];
      c.filters.status = ''; c.filters.search = ''; c.kpiFilter = '';
      c.zoneSearch = ''; c.regionSearch = ''; c.depotSearch = '';
      c.closeAllDropdowns();
      c.applyFilters();
  };

  // ===================== SEGMENT multiselect =====================
  c.segmentDropdownOpen = false; c.segmentSearch = '';
  c.openSegmentDropdown = function() { c.closeAllDropdowns(); c.segmentDropdownOpen = true; };
  c.closeSegmentDropdown = function() { c.segmentDropdownOpen = false; };
  function resetBelowSegment() { c.filters.regions = []; c.filters.depots = []; c.regionSearch = ''; c.depotSearch = ''; }
  c.toggleSegment = function(sg) {
      var idx = c.filters.segments.indexOf(sg);
      if (idx === -1) c.filters.segments.push(sg); else c.filters.segments.splice(idx, 1);
      resetBelowSegment(); c.segmentSearch = ''; c.applyFilters();
  };
  c.selectAllSegments = function() {
      c.filters.segments = (((c.data || {}).filterOpts || {}).segments || []).slice();
      resetBelowSegment(); c.segmentSearch = ''; c.applyFilters();
  };
  c.clearAllSegments = function() { c.filters.segments = []; resetBelowSegment(); c.segmentSearch = ''; c.applyFilters(); };
  c.isSegmentSelected = function(sg) { return c.filters.segments.indexOf(sg) !== -1; };
  c.getFilteredSegments = function() {
      var all = (c.data && c.data.filterOpts && c.data.filterOpts.segments) || [];
      var term = (c.segmentSearch || '').toLowerCase();
      return term ? all.filter(function(s) { return String(s).toLowerCase().indexOf(term) !== -1; }) : all;
  };
  c.getSegmentDisplayText = function() {
      if (!c.filters.segments.length) return 'All Segments';
      if (c.filters.segments.length === 1) return c.filters.segments[0];
      return c.filters.segments.length + ' segments selected';
  };

  // ===================== ZONE multiselect =====================
  c.zoneDropdownOpen = false; c.zoneSearch = '';
  c.openZoneDropdown = function() { c.closeAllDropdowns(); c.zoneDropdownOpen = true; };
  c.closeZoneDropdown = function() { c.zoneDropdownOpen = false; };
  c.toggleZone = function(z) {
      var idx = c.filters.zones.indexOf(z);
      if (idx === -1) c.filters.zones.push(z); else c.filters.zones.splice(idx, 1);
      c.filters.regions = []; c.filters.depots = []; c.zoneSearch = ''; c.applyFilters();
  };
  c.selectAllZones = function() {
      c.filters.zones = (((c.data || {}).filterOpts || {}).zones || []).slice();
      c.filters.regions = []; c.filters.depots = []; c.zoneSearch = ''; c.applyFilters();
  };
  c.clearAllZones = function() { c.filters.zones = []; c.filters.regions = []; c.filters.depots = []; c.zoneSearch = ''; c.applyFilters(); };
  c.isZoneSelected = function(z) { return c.filters.zones.indexOf(z) !== -1; };
  c.getFilteredZones = function() {
      var all = (c.data && c.data.filterOpts && c.data.filterOpts.zones) || [];
      var term = (c.zoneSearch || '').toLowerCase();
      return term ? all.filter(function(z) { return String(z).toLowerCase().indexOf(term) !== -1; }) : all;
  };
  c.getZoneDisplayText = function() {
      if (!c.filters.zones.length) return 'All Zones';
      if (c.filters.zones.length === 1) return c.filters.zones[0];
      return c.filters.zones.length + ' zones selected';
  };

  // ===================== REGION multiselect =====================
  c.regionDropdownOpen = false; c.regionSearch = '';
  c.openRegionDropdown = function() { c.closeAllDropdowns(); c.regionDropdownOpen = true; };
  c.closeRegionDropdown = function() { c.regionDropdownOpen = false; };
  c.toggleRegion = function(r) {
      var idx = c.filters.regions.indexOf(r);
      if (idx === -1) c.filters.regions.push(r); else c.filters.regions.splice(idx, 1);
      c.filters.depots = []; c.regionSearch = ''; c.applyFilters();
  };
  c.selectAllRegions = function() {
      c.filters.regions = (((c.data || {}).filterOpts || {}).regions || []).slice();
      c.filters.depots = []; c.regionSearch = ''; c.applyFilters();
  };
  c.clearAllRegions = function() { c.filters.regions = []; c.filters.depots = []; c.regionSearch = ''; c.applyFilters(); };
  c.isRegionSelected = function(r) { return c.filters.regions.indexOf(r) !== -1; };
  c.getFilteredRegions = function() {
      var all = (c.data && c.data.filterOpts && c.data.filterOpts.regions) || [];
      var term = (c.regionSearch || '').toLowerCase();
      return term ? all.filter(function(r) { return String(r).toLowerCase().indexOf(term) !== -1; }) : all;
  };
  c.getRegionDisplayText = function() {
      if (!c.filters.regions.length) return 'All Regions';
      if (c.filters.regions.length === 1) return c.filters.regions[0];
      return c.filters.regions.length + ' regions selected';
  };

  // ===================== DEPOT multiselect =====================
  c.depotDropdownOpen = false; c.depotSearch = '';
  c.openDepotDropdown = function() { c.closeAllDropdowns(); c.depotDropdownOpen = true; };
  c.closeDepotDropdown = function() { c.depotDropdownOpen = false; };
  c.toggleDepot = function(d) {
      var idx = c.filters.depots.indexOf(d);
      if (idx === -1) c.filters.depots.push(d); else c.filters.depots.splice(idx, 1);
      c.depotSearch = ''; c.applyFilters();
  };
  c.selectAllDepots = function() {
      c.filters.depots = (((c.data || {}).filterOpts || {}).depots || []).slice();
      c.depotSearch = ''; c.applyFilters();
  };
  c.clearAllDepots = function() { c.filters.depots = []; c.depotSearch = ''; c.applyFilters(); };
  c.isDepotSelected = function(d) { return c.filters.depots.indexOf(d) !== -1; };
  c.getFilteredDepots = function() {
      var all = (c.data && c.data.filterOpts && c.data.filterOpts.depots) || [];
      var term = (c.depotSearch || '').toLowerCase();
      return term ? all.filter(function(d) { return String(d).toLowerCase().indexOf(term) !== -1; }) : all;
  };
  c.getDepotDisplayText = function() {
      if (!c.filters.depots.length) return 'All Depots';
      if (c.filters.depots.length === 1) return c.filters.depots[0];
      return c.filters.depots.length + ' depots selected';
  };

  // ===================== Filter helpers =====================
  c.hasActiveFilters = function() {
      var f = c.filters;
      return !!(f.segments.length || f.zones.length || f.regions.length || f.depots.length ||
                f.status || (f.period && f.period !== 'latest'));
  };

  c.clearAllFilters = function() {
      c.filters.segments = []; c.filters.zones = []; c.filters.regions = []; c.filters.depots = [];
      c.filters.status = ''; c.filters.period = 'latest';
      c.closeAllDropdowns();
      c.applyFilters();
  };

  c.openRequestDetail = function(r) {
      if (!r || !r.requestCode) return;
      var biz = HOST_KEY[c.filters.business] || c.filters.business;
      $rootScope.clmPendingRequestNumber = r.requestCode;
      $rootScope.clmPendingRequestBusiness = biz;
      $rootScope.$broadcast('clm.request.selected', { number: r.requestCode, business: biz });
      $rootScope.$broadcast('clm.switch.tab', 'request_detail');
  };

  c.applyFilters = function() {
    c.pagination.currentPage = 1;
    c.data.filters = {
      business: c.filters.business, segments: c.filters.segments, zones: c.filters.zones,
      regions: c.filters.regions, depots: c.filters.depots, status: c.filters.status, period: c.filters.period
    };
    c.server.update().then(function() {
      if (c.data && c.data.selectedBusiness) c.filters.business = c._lastBusiness = c.data.selectedBusiness;
      if (c.data && c.data.selectedPeriod)   c.filters.period = c.data.selectedPeriod;
      c.buildChartScale();
      c.onMouseLeaveChart();
      c.runSearch();
    });
  };

  c.scrollToTable = function() {
      $timeout(function() {
          var el = document.getElementById('clmRequestsTableContainer');
          if (el) el.scrollIntoView({ behavior: 'smooth', block: 'start' });
      }, 100);
  };

  c.setKpiFilter = function(state) {
      state = state || '';
      if (!state) { c.kpiFilter = ''; c.scrollToTable(); }
      else if (c.kpiFilter === state) { c.kpiFilter = ''; }
      else { c.kpiFilter = state; c.scrollToTable(); }
      c.pagination.currentPage = 1;
      c.runSearch();
  };

  c.runSearch = function() {
    var term = (c.filters.search || '').toString().toLowerCase().trim();
    (c.data.requests || []).forEach(function(r) {
      var isHidden = false;
      if (term) {
        var fields = [r.requestCode, r.pan, r.customerNames, r.customerCodes];
        if (!fields.some(function(f) { return (f || '').toString().toLowerCase().indexOf(term) > -1; })) isHidden = true;
      }
      if (!isHidden && c.kpiFilter) {
          if (c.kpiFilter === 'deviated') { if (!r.isDeviation) isHidden = true; }
          else if (r.status !== c.kpiFilter) isHidden = true;
      }
      r._hidden = isHidden;
    });
    c.pagination.currentPage = 1;
    c.updatePaginatedRequests();
  };

  c.updatePaginatedRequests = function() {
    var visible = (c.data.requests || []).filter(function(r) { return !r._hidden; });
    var start = (c.pagination.currentPage - 1) * c.pagination.rowsPerPage;
    c.paginatedRequests = visible.slice(start, start + c.pagination.rowsPerPage);
  };
  c.getVisibleRecordsCount = function() { return (c.data.requests || []).filter(function(r) { return !r._hidden; }).length; };
  c.getTotalPages = function() { return Math.ceil(c.getVisibleRecordsCount() / c.pagination.rowsPerPage) || 1; };
  c.getPageNumbers = function() {
    var total = c.getTotalPages(), pages = [], maxVisible = 5;
    var start = Math.max(1, c.pagination.currentPage - Math.floor(maxVisible / 2));
    var end = Math.min(total, start + maxVisible - 1);
    if (end - start < maxVisible - 1) start = Math.max(1, end - maxVisible + 1);
    for (var i = start; i <= end; i++) pages.push(i);
    return pages;
  };
  c.previousPage = function() { if (c.pagination.currentPage > 1) { c.pagination.currentPage--; c.updatePaginatedRequests(); } };
  c.nextPage = function() { if (c.pagination.currentPage < c.getTotalPages()) { c.pagination.currentPage++; c.updatePaginatedRequests(); } };
  c.goToPage = function(p) { c.pagination.currentPage = p; c.updatePaginatedRequests(); };
  c.onRowsPerPageChange = function() { c.pagination.currentPage = 1; c.updatePaginatedRequests(); };

  $scope.$watch('c.filters.search', c.runSearch);

  // ===================== Chart =====================
  var PLOT_W = 1000, PLOT_H = 200;
  c.chartScale = { top: 4, ticks: [0, 1, 2, 3, 4] };

  c.buildChartScale = function() {
    var max = (c.data.chart && c.data.chart.max) || 0;
    var step, top;
    if (max <= 4) { step = 1; top = 4; }
    else {
      var raw = max / 4, mag = Math.pow(10, Math.floor(Math.log(raw) / Math.LN10)), r = raw / mag;
      step = (r <= 1 ? 1 : r <= 2 ? 2 : r <= 2.5 ? 2.5 : r <= 5 ? 5 : 10) * mag;
      if (step < 1) step = 1;
      top = step * Math.ceil(max / step);
    }
    var ticks = [];
    for (var v = 0; v <= top + 1e-9; v += step) ticks.push(Math.round(v * 100) / 100);
    c.chartScale = { top: top, ticks: ticks };
  };
  function monthCount() { return ((c.data.chart && c.data.chart.months) || []).length; }
  c.chartX = function(i) { var n = monthCount(); return n <= 1 ? PLOT_W / 2 : i * (PLOT_W / (n - 1)); };
  c.chartY = function(v) { return PLOT_H - ((v || 0) / (c.chartScale.top || 1)) * PLOT_H; };
  c.xPct = function(i) { return c.chartX(i) / PLOT_W * 100; };
  c.yPct = function(v) { return c.chartY(v) / PLOT_H * 100; };
  c.colWidth = function() { var n = monthCount(); return n <= 1 ? PLOT_W : PLOT_W / (n - 1); };
  c.linePoints = function(key) {
    var months = (c.data.chart && c.data.chart.months) || [];
    var s = ((c.data.chart && c.data.chart.series) || {})[key] || [];
    return months.map(function(m, i) { return c.chartX(i) + ',' + c.chartY(s[i] || 0); }).join(' ');
  };
  c.onMouseOverMonth = function(ev, index) { c.hoverIndex = index; c.showTooltip = true; };
  c.onMouseLeaveChart = function() { c.hoverIndex = -1; c.showTooltip = false; };

  // ===================== Badges =====================
  c.statusClass = function(status) {
    var s = (status || '').toLowerCase();
    if (s === 'pending') return 'st-submitted';
    if (s === 'approved') return 'st-approved';
    if (s === 'rejected') return 'st-rejected';
    return 'st-default';
  };
  c.segClass = function(seg) {
    var s = (seg || '').toLowerCase();
    if (s.indexOf('cement') > -1) return 'seg-cement';
    if (s.indexOf('rmc') > -1) return 'seg-rmc';
    if (s.indexOf('bpd') > -1) return 'seg-bpd';
    return 'seg-default';
  };

  c.buildChartScale();
  c.updatePaginatedRequests();
  if (c.data.initialLoad) c.applyFilters();
}

sp_widget.css:
/*
  CLM – Non-Trade Approval Requests (NSH)  v1.0
  Same design system as the Trade / Non-Trade MD approval widgets.
  - Series key 'pending' (.k-pending), multi-customer cell (.clm-ar-cust-item / .clm-ar-more)
  - 11-column table (Zone / Region / Depot columns removed)
*/
@import url('https://fonts.googleapis.com/css2?family=Oxygen:wght@300;400;700&display=swap');

.clm-ar {
  color: #1a1a1a;
  font-size: 13px;
  padding: 20px;
  background: #f4f5f7;
}

/* ===================== Card (block) ===================== */
.clm-ar .clm-block { margin: 0 0 16px; background: #fff; border: 1px solid #dde3ea; border-radius: 8px; }
.clm-ar .clm-block-head {
  display: flex; align-items: center; justify-content: space-between; gap: 12px 20px; flex-wrap: wrap;
  padding: 14px 20px; background: #fafbfc; border-bottom: 1px solid #dde3ea; border-radius: 8px 8px 0 0;
}
.clm-ar .clm-block-title {
  display: flex; align-items: center; gap: 10px; font-size: 13px; font-weight: 700; color: #1a1a1a;
  text-transform: uppercase; letter-spacing: .8px;
}
.clm-ar .clm-block-title::before { content: ""; width: 4px; height: 16px; border-radius: 2px; background: #F3D54E; flex-shrink: 0; }
.clm-ar .clm-block-sub { margin: 4px 0 0 14px; font-size: 12px; color: #5a6a7a; }
.clm-ar .clm-block-meta { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.clm-ar .clm-chip {
  display: inline-flex; align-items: center; gap: 6px; padding: 4px 10px; background: #fff;
  border: 1px solid #dde3ea; border-radius: 12px; font-size: 12px; font-weight: 700; color: #1a1a1a; white-space: nowrap;
}
.clm-ar .clm-chip-k { font-weight: 400; color: #5a6a7a; }
.clm-ar .clm-tw-body { padding: 18px 20px; }
.clm-ar .clm-no-data { text-align: center; color: #7f8c9a; padding: 24px 0; font-style: italic; }

.clm-ar .clm-ar-clear {
  padding: 4px 12px; background: #fff; border: 1px solid #cdd4dc; border-radius: 12px;
  font-size: 12px; font-weight: 700; color: #3a4451; cursor: pointer;
}
.clm-ar .clm-ar-clear:hover { background: #1a1a1a; border-color: #1a1a1a; color: #F3D54E; }

/* ===================== Filters ===================== */
.clm-ar .clm-ar-filters .clm-tw-body { padding: 16px 20px; }
.clm-ar .clm-filter-row { display: grid; grid-template-columns: repeat(7, minmax(0, 1fr)); gap: 14px; }
.clm-ar .clm-filter-field {
  display: flex; flex-direction: column; gap: 6px; margin: 0; min-width: 0; position: relative; font-weight: 400;
}
.clm-ar .clm-filter-k { font-size: 12px; font-weight: 700; color: #3a4451; text-transform: uppercase; letter-spacing: .6px; }
.clm-ar .clm-filter-field select {
  width: 100%; height: 36px; font-size: 13px; color: #1a1a1a; border-radius: 6px; border: 1px solid #cdd4dc;
  background-color: #fff; padding: 0 10px; outline: none; cursor: pointer; box-shadow: none; box-sizing: border-box;
}
.clm-ar .clm-filter-field select:hover { border-color: #a0aab6; }
.clm-ar .clm-filter-field select:focus { border-color: #1a1a1a; box-shadow: 0 0 0 2px rgba(243, 213, 78, .45); }
.clm-ar .clm-ar-biz-select option:disabled { color: #b0b9c4; }

/* ---------- Multiselect ---------- */
.clm-ar .clm-multiselect-container { position: relative; width: 100%; }
.clm-ar .clm-multiselect-trigger {
  display: flex; align-items: center; justify-content: space-between; width: 100%; height: 36px; padding: 0 10px;
  font-size: 13px; border: 1px solid #cdd4dc; border-radius: 6px; background: #fff; cursor: pointer; box-sizing: border-box;
}
.clm-ar .clm-multiselect-trigger:hover { border-color: #a0aab6; }
.clm-ar .clm-multiselect-container.open .clm-multiselect-trigger {
  border-color: #1a1a1a; border-bottom-left-radius: 0; border-bottom-right-radius: 0;
}
.clm-ar .clm-multiselect-text { flex: 1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; color: #1a1a1a; }
.clm-ar .clm-multiselect-arrow { color: #7f8c9a; font-size: 10px; margin-left: 6px; }
.clm-ar .clm-multiselect-dropdown {
  position: absolute; top: 36px; left: 0; right: 0; min-width: 220px; z-index: 60; background: #fff;
  border: 1px solid #1a1a1a; border-top: none; border-radius: 0 0 6px 6px; box-shadow: 0 8px 18px rgba(0, 0, 0, .12);
  max-height: 300px; display: flex; flex-direction: column; overflow: hidden;
}
.clm-ar .clm-multiselect-actions {
  display: flex; justify-content: space-between; padding: 7px 12px; border-bottom: 1px solid #e6eaef; background: #fafbfc;
}
.clm-ar .clm-multiselect-actions a { font-size: 12px; font-weight: 700; color: #3a4451; cursor: pointer; }
.clm-ar .clm-multiselect-actions a:hover { text-decoration: underline; }
.clm-ar .clm-multiselect-search {
  width: 100%; height: 34px; padding: 0 12px; border: none; border-bottom: 1px solid #e6eaef;
  font-size: 12.5px; outline: none; box-sizing: border-box;
}
.clm-ar .clm-multiselect-list { list-style: none; margin: 0; padding: 4px 0; overflow-y: auto; max-height: 190px; }
.clm-ar .clm-multiselect-list li {
  display: flex; align-items: center; gap: 8px; padding: 7px 12px; font-size: 13px; color: #1a1a1a; cursor: pointer;
}
.clm-ar .clm-multiselect-list li:hover { background: #f4f5f7; }
.clm-ar .clm-multiselect-list li.selected { background: #fffcf0; font-weight: 700; }
.clm-ar .clm-checkbox {
  width: 14px; height: 14px; border: 2px solid #cdd4dc; border-radius: 3px; display: inline-block; flex-shrink: 0; position: relative;
}
.clm-ar .clm-checkbox.checked { background: #1a1a1a; border-color: #1a1a1a; }
.clm-ar .clm-checkbox.checked::after {
  content: ''; position: absolute; left: 3px; top: 0; width: 4px; height: 8px;
  border: solid #F3D54E; border-width: 0 2px 2px 0; transform: rotate(45deg);
}
.clm-ar .clm-dropdown-empty { color: #7f8c9a !important; cursor: default !important; font-style: italic; }
.clm-ar .clm-dropdown-empty:hover { background: #fff !important; }

/* ===================== Status tiles ===================== */
.clm-ar .clm-ar-stats { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 12px; margin: 0 0 16px; }
.clm-ar .clm-ar-stat {
  display: flex; flex-direction: column; align-items: flex-start; gap: 6px; padding: 14px 16px; background: #fff;
  border: 1px solid #dde3ea; border-top: 4px solid #cdd4dc; border-radius: 8px; cursor: pointer; text-align: left;
  transition: box-shadow .2s, background-color .2s; outline: none;
}
.clm-ar .clm-ar-stat:hover { box-shadow: 0 3px 10px rgba(0, 0, 0, .06); }
.clm-ar .clm-ar-stat-k { font-size: 12px; font-weight: 700; color: #3a4451; text-transform: uppercase; letter-spacing: .6px; }
.clm-ar .clm-ar-stat-v { font-size: 26px; font-weight: 700; line-height: 1.1; }
.clm-ar .clm-ar-stat-s { font-size: 11px; color: #7f8c9a; }
.clm-ar .clm-ar-stat.st-total    { border-top-color: #1a1a1a; } .clm-ar .st-total    .clm-ar-stat-v { color: #1a1a1a; }
.clm-ar .clm-ar-stat.st-pending  { border-top-color: #2e86c1; } .clm-ar .st-pending  .clm-ar-stat-v { color: #2e86c1; }
.clm-ar .clm-ar-stat.st-approved { border-top-color: #27ae60; } .clm-ar .st-approved .clm-ar-stat-v { color: #27ae60; }
.clm-ar .clm-ar-stat.st-rejected { border-top-color: #E23D28; } .clm-ar .st-rejected .clm-ar-stat-v { color: #E23D28; }
.clm-ar .clm-ar-stat.st-deviated { border-top-color: #E87722; } .clm-ar .st-deviated .clm-ar-stat-v { color: #E87722; }
.clm-ar .clm-ar-stat.is-active {
  background: #fffcf0; border-color: #F3D54E; box-shadow: 0 0 0 2px rgba(243, 213, 78, .35);
}
.clm-ar .clm-ar-stat.is-active.st-total    { border-top-color: #1a1a1a; }
.clm-ar .clm-ar-stat.is-active.st-pending  { border-top-color: #2e86c1; }
.clm-ar .clm-ar-stat.is-active.st-approved { border-top-color: #27ae60; }
.clm-ar .clm-ar-stat.is-active.st-rejected { border-top-color: #E23D28; }
.clm-ar .clm-ar-stat.is-active.st-deviated { border-top-color: #E87722; }

/* ===================== Chart ===================== */
.clm-ar .k-total    { --k: #1a1a1a; }
.clm-ar .k-pending  { --k: #2e86c1; }
.clm-ar .k-approved { --k: #27ae60; }
.clm-ar .k-rejected { --k: #E23D28; }

.clm-ar .clm-ar-legend { gap: 6px 14px; }
.clm-ar .clm-ar-leg { display: inline-flex; align-items: center; gap: 6px; font-size: 12px; font-weight: 700; color: #3a4451; }
.clm-ar .clm-ar-sw { width: 10px; height: 10px; border-radius: 2px; display: inline-block; background: var(--k); flex-shrink: 0; }

.clm-ar .clm-ar-chart-body { padding: 8px 28px 30px 40px; }
.clm-ar .clm-ar-plot { position: relative; height: 240px; }
.clm-ar .clm-ar-svg { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; display: block; }
.clm-ar .clm-ar-svg line, .clm-ar .clm-ar-svg polyline { vector-effect: non-scaling-stroke; }
.clm-ar .clm-ar-grid { stroke: #eef1f5; stroke-width: 1; }
.clm-ar .clm-ar-grid.is-base { stroke: #c9d1db; }
.clm-ar .clm-ar-guide { stroke: #8a96a3; stroke-width: 1; stroke-dasharray: 4 4; }
.clm-ar .clm-ar-line { fill: none; stroke: var(--k); stroke-width: 2.5; stroke-linejoin: round; stroke-linecap: round; }
.clm-ar .clm-ar-line.k-total { stroke-width: 2; stroke-dasharray: 6 5; }
.clm-ar .clm-ar-hit { fill: transparent; cursor: crosshair; }

.clm-ar .clm-ar-ytick {
  position: absolute; right: calc(100% + 10px); transform: translateY(-50%);
  font-size: 11.5px; color: #7f8c9a; font-variant-numeric: tabular-nums; pointer-events: none;
}
.clm-ar .clm-ar-xtick {
  position: absolute; top: calc(100% + 10px); transform: translateX(-50%); white-space: nowrap;
  font-size: 11.5px; color: #5a6a7a; pointer-events: none;
}
.clm-ar .clm-ar-xtick.is-current, .clm-ar .clm-ar-xtick.is-hover { color: #1a1a1a; font-weight: 700; }
.clm-ar .clm-ar-mtd {
  margin-left: 4px; padding: 0 5px; border-radius: 8px; background: #fff8e1; border: 1px solid #F3D54E;
  font-size: 9.5px; font-weight: 700; color: #7a5a00; vertical-align: 1px;
}
.clm-ar .clm-ar-pt {
  position: absolute; width: 10px; height: 10px; margin: -5px 0 0 -5px; border-radius: 50%;
  background: #fff; border: 2.5px solid var(--k); box-sizing: border-box; pointer-events: none;
}

.clm-ar .clm-ar-tip {
  position: absolute; top: 0; transform: translateX(14px); z-index: 20; min-width: 170px;
  padding: 10px 12px; background: #1a1a1a; color: #fff; border-radius: 6px;
  box-shadow: 0 6px 16px rgba(0, 0, 0, .2); pointer-events: none; font-size: 12px;
}
.clm-ar .clm-ar-tip.is-flip { transform: translateX(calc(-100% - 14px)); }
.clm-ar .clm-ar-tip .k-total { --k: #ffffff; }
.clm-ar .clm-ar-tip-t {
  margin-bottom: 6px; padding-bottom: 6px; border-bottom: 1px solid rgba(255, 255, 255, .18);
  font-weight: 700; color: #F3D54E;
}
.clm-ar .clm-ar-tip-r { display: flex; align-items: center; gap: 8px; margin: 4px 0; }
.clm-ar .clm-ar-tip-k { flex: 1; color: #d6dbe1; }
.clm-ar .clm-ar-tip-v { font-weight: 700; font-variant-numeric: tabular-nums; }

/* ===================== Requests table ===================== */
.clm-ar .clm-ar-toolbar {
  display: flex; align-items: center; justify-content: space-between; gap: 12px; flex-wrap: wrap; padding: 14px 20px;
}
.clm-ar .clm-search-box { position: relative; display: flex; align-items: center; width: 420px; max-width: 100%; }
.clm-ar .clm-search-box i { position: absolute; left: 12px; color: #7f8c9a; font-size: 13px; }
.clm-ar .clm-search-box input {
  width: 100%; height: 36px; border: 1px solid #cdd4dc; border-radius: 6px; padding: 0 10px 0 34px;
  font-size: 13px; color: #1a1a1a; outline: none; box-sizing: border-box;
}
.clm-ar .clm-search-box input:focus { border-color: #1a1a1a; box-shadow: 0 0 0 2px rgba(243, 213, 78, .45); }
.clm-ar .clm-search-box input::placeholder { color: #7f8c9a; }
.clm-ar .clm-rows-label {
  display: flex; align-items: center; gap: 8px; margin: 0; font-size: 12px; font-weight: 700;
  color: #3a4451; text-transform: uppercase; letter-spacing: .6px;
}
.clm-ar .clm-rows-select {
  height: 34px; padding: 0 8px; min-width: 64px; font-size: 13px; color: #1a1a1a; border: 1px solid #cdd4dc;
  border-radius: 6px; background: #fff; cursor: pointer; outline: none;
}
.clm-ar .clm-ar-kpi-chip { cursor: pointer; background: #fffcf0; border-color: #F3D54E; }
.clm-ar .clm-ar-kpi-chip .clm-ar-x { color: #5a6a7a; font-size: 11px; }
.clm-ar .clm-ar-kpi-chip:hover .clm-ar-x { color: #1a1a1a; }

.clm-ar .clm-table-wrap {
  overflow: auto; max-height: 520px; border-top: 1px solid #dde3ea; border-bottom: 1px solid #dde3ea; background: #fff;
}
.clm-ar .clm-table { width: 100%; border-collapse: collapse; font-size: 13px; font-variant-numeric: tabular-nums; margin: 0; }
.clm-ar .clm-table th {
  background: #eef1f5; color: #2b3440; padding: 10px; font-size: 11px; font-weight: 700;
  text-transform: uppercase; letter-spacing: .6px; text-align: center; white-space: nowrap;
  border: 0; border-bottom: 1px solid #dde3ea;
}
.clm-ar .clm-table thead { position: sticky; top: 0; z-index: 3; }
.clm-ar .clm-table td {
  padding: 10px; color: #1a1a1a; text-align: center; white-space: nowrap; border: 0; border-bottom: 1px solid #e6eaef; vertical-align: middle;
}
.clm-ar .clm-table tr > :first-child { padding-left: 20px; }
.clm-ar .clm-table tr > :last-child  { padding-right: 20px; }
.clm-ar .clm-table tbody tr:last-child td  { border-bottom: 0; }
.clm-ar .clm-table tbody tr:hover td { background: #fafbfc; }

.clm-ar .clm-ar-table td:nth-child(1), .clm-ar .clm-ar-table td:nth-child(2),
.clm-ar .clm-ar-table thead tr:last-child th:nth-child(1),
.clm-ar .clm-ar-table thead tr:last-child th:nth-child(2) { text-align: left; }
.clm-ar .clm-ar-table { font-size: 12.5px; }
.clm-ar .clm-ar-table th { padding: 10px 7px; font-size: 10.5px; letter-spacing: .4px; }
.clm-ar .clm-ar-table td { padding: 10px 7px; }
.clm-ar .clm-ar-table td.col-customer { white-space: normal; min-width: 170px; max-width: 240px; }
.clm-ar .clm-ar-table td.num { text-align: right; }
.clm-ar .clm-ar-table td.num-key { font-weight: 700; }
.clm-ar .clm-ar-table td.col-submitted-by { text-align: left; white-space: normal; min-width: 150px; }
.clm-ar .clm-ar-mono { letter-spacing: .3px; }
.clm-ar .clm-ar-faint { color: #b0b9c4; }
.clm-ar .clm-ar-by { white-space: nowrap; }
.clm-ar .clm-ar-on { margin-top: 2px; font-size: 11px; color: #7f8c9a; }

.clm-ar .clm-link { color: #0b5394; font-weight: 700; text-decoration: none; }
.clm-ar .clm-link:hover { text-decoration: underline; }
.clm-ar .clm-cust-name { font-weight: 700; color: #1a1a1a; }
.clm-ar .clm-cust-code { margin-top: 2px; font-size: 12px; font-weight: 600; color: #5a6a7a; }
.clm-ar .clm-ar-cust-item + .clm-ar-cust-item { margin-top: 6px; padding-top: 6px; border-top: 1px dashed #e6eaef; }
.clm-ar .clm-ar-more { margin-top: 6px; font-size: 11.5px; font-weight: 700; color: #0b5394; cursor: help; }

/* badges */
.clm-ar .badge {
  display: inline-block; padding: 3px 10px; border-radius: 12px; border: 1px solid transparent;
  font-size: 11.5px; font-weight: 700; line-height: 1.4; white-space: nowrap;
}
.clm-ar .status-badge.st-submitted { background: #eaf3fa; color: #1f6c9e; border-color: #b9d8ee; }
.clm-ar .status-badge.st-approved  { background: #eaf7ee; color: #1e8449; border-color: #b9e3c6; }
.clm-ar .status-badge.st-rejected  { background: #fdecea; color: #b3261e; border-color: #f5c2bc; }
.clm-ar .status-badge.st-default   { background: #f4f5f7; color: #5a6a7a; border-color: #dde3ea; }
.clm-ar .clm-ar-dev { display: block; width: fit-content; margin: 4px auto 0; background: #fdecea; color: #b3261e; border-color: #f5c2bc; }
.clm-ar .stage-badge { background: #fff; color: #1a1a1a; border-color: #dde3ea; }
.clm-ar .stage-badge i { color: #7f8c9a; margin-right: 2px; }
.clm-ar .seg-badge { border-radius: 4px; margin: 1px 2px; }
.clm-ar .seg-badge.seg-cement  { background: #f1f3f7; color: #3a4451; border-color: #dde3ea; }
.clm-ar .seg-badge.seg-rmc     { background: #e6f4ea; color: #2e7d32; border-color: #c4e3cc; }
.clm-ar .seg-badge.seg-bpd     { background: #fdf3e1; color: #a35400; border-color: #f3d9ad; }
.clm-ar .seg-badge.seg-default { background: #f4f5f7; color: #5a6a7a; border-color: #dde3ea; }

/* pagination */
.clm-ar .clm-pagination-bottom {
  display: flex; justify-content: space-between; align-items: center; gap: 10px; flex-wrap: wrap; padding: 12px 20px;
}
.clm-ar .clm-ar-pageinfo { font-size: 12px; color: #5a6a7a; }
.clm-ar .clm-pagination-controls { display: flex; gap: 4px; flex-wrap: wrap; }
.clm-ar .clm-page-btn {
  min-width: 32px; height: 32px; padding: 0 8px; border: 1px solid #cdd4dc; border-radius: 6px; background: #fff;
  color: #3a4451; font-size: 12.5px; font-weight: 700; display: flex; align-items: center; justify-content: center; cursor: pointer;
}
.clm-ar .clm-page-btn:hover:not(:disabled) { background: #f4f5f7; }
.clm-ar .clm-page-btn.active { background: #1a1a1a; border-color: #1a1a1a; color: #F3D54E; }
.clm-ar .clm-page-btn:disabled { color: #b0b9c4; background: #fafbfc; border-color: #e6eaef; cursor: not-allowed; }

/* ===================== Responsive ===================== */
@media (max-width: 1280px) {
  .clm-ar .clm-filter-row { grid-template-columns: repeat(4, minmax(0, 1fr)); }
}
@media (max-width: 1100px) {
  .clm-ar .clm-ar-stats { grid-template-columns: repeat(3, minmax(0, 1fr)); }
}
@media (max-width: 768px) {
  .clm-ar { padding: 12px; }
  .clm-ar .clm-filter-row { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .clm-ar .clm-ar-stats { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .clm-ar .clm-ar-stat.st-total { grid-column: 1 / -1; }
  .clm-ar .clm-ar-legend { width: 100%; }
  .clm-ar .clm-ar-plot { height: 200px; }
  .clm-ar .clm-ar-chart-body { padding-left: 30px; }
  .clm-ar .clm-ar-xtick.is-skip { visibility: hidden; }
  .clm-ar .clm-ar-xtick.is-current, .clm-ar .clm-ar-xtick.is-hover { visibility: visible; }
  .clm-ar .clm-ar-mtd { display: none; }

  /* table -> label / value cards */
  .clm-ar .clm-table-wrap { max-height: none; border: 0; background: #f4f5f7; padding: 12px; }
  .clm-ar .clm-ar-table thead { display: none; }
  .clm-ar .clm-ar-table, .clm-ar .clm-ar-table tbody, .clm-ar .clm-ar-table tr, .clm-ar .clm-ar-table td { display: block; width: 100%; }
  .clm-ar .clm-ar-table tr { margin-bottom: 12px; background: #fff; border: 1px solid #dde3ea; border-radius: 8px; overflow: hidden; }
  .clm-ar .clm-ar-table td {
    display: flex; justify-content: flex-end; align-items: center; flex-wrap: wrap; gap: 6px 8px; box-sizing: border-box;
    padding: 9px 14px; border: 0 !important; border-bottom: 1px solid #eef1f5 !important;
    text-align: right !important; white-space: normal; max-width: none !important; min-width: 0 !important;
  }
  .clm-ar .clm-ar-table td::before {
    content: attr(data-label); flex-shrink: 0; font-size: 11.5px; font-weight: 700; color: #5a6a7a;
    text-transform: uppercase; letter-spacing: .5px; text-align: left; margin-right: auto;
  }
  .clm-ar .clm-ar-table .clm-ar-dev { margin: 0; }
  .clm-ar .clm-ar-by { white-space: normal; overflow-wrap: anywhere; }
  .clm-ar .clm-ar-table td:first-child { background: #fafbfc; }
  .clm-ar .clm-ar-table td:last-child { border-bottom: 0 !important; }
  .clm-ar .clm-ar-table td.col-customer, .clm-ar .clm-ar-table td.col-submitted-by { display: block; }
  .clm-ar .clm-ar-table td.col-customer::before,
  .clm-ar .clm-ar-table td.col-submitted-by::before { display: block; margin-bottom: 4px; }
  .clm-ar .clm-ar-table td.col-customer, .clm-ar .clm-ar-table td.col-submitted-by { text-align: left !important; }
  .clm-ar .clm-ar-table tr.clm-ar-empty td { display: block; text-align: center !important; }
  .clm-ar .clm-ar-table tr.clm-ar-empty td::before { content: none; }
}
@media (max-width: 640px) {
  .clm-ar .clm-filter-row { grid-template-columns: 1fr; }
  .clm-ar .clm-ar-stat-v { font-size: 22px; }
  .clm-ar .clm-search-box { width: 100%; }
}

/* ===================== One font family (keep LAST) ===================== */
.clm-widget, .clm-widget *, .clm-widget input, .clm-widget select,
.clm-widget textarea, .clm-widget button, .clm-widget table {
  font-family: "Oxygen", "Source Sans Pro", "Helvetica Neue", Helvetica, Arial, sans-serif !important;
}
.clm-widget .fa { font-family: FontAwesome !important; }

sp_widget.script:
/*
  CLM – Non-Trade Approval Requests (Zonal: ZHM / ZCH) – Server Script  v1.0

  ACCESS / SCOPE (x_birl3_clm_approval_matrix)
    approver_user = logged-in user, role_name in the ZHM Non-Trade roles
      (from CLMBusinessAccess.RULES.ZHM.nonTrade.roles, fallback list below)
    SEGMENT comes from the ROLE:  NT CEMENT ZCH / ZHM -> Cement,  NT RMC ZCH / ZH -> RMC,
                                  NT BPD ZCH / ZH BPD -> BPD
    ZONE comes from the matrix row's zone (one or several, comma-separated or several rows).
      blank zone or pan_india = true -> every zone (still limited to the role's segment)
    Region / Depot on the matrix are not used: the user sees every region / depot of the master
      that sits under his zones.
  DATA
    x_birl3_clm_nt_pan_request, x_birl3_clm_nt_site_request (pan_request -> customer_site_code),
    customer master (cg1 = N01), x_birl3_clm_clm_aging_snapshot (customer.cg1 = N01)
*/
(function() {

    var DEFAULT_BUSINESS = 'non_trade';
    var BUSINESS_LABELS  = { trade: 'Trade', non_trade: 'Non-Trade', key: 'Key' };
    var BUSINESS_ORDER   = ['trade', 'non_trade', 'key'];
    var BUSINESS_BUILT   = { trade: true, non_trade: true, key: true };
    var PERSONA = 'ZHM';

    var NT_ROLES_FALLBACK = ['NT CEMENT ZCH', 'NT CEMENT ZHM', 'NT RMC ZCH', 'NT RMC ZH', 'NT BPD ZCH', 'NT BPD ZH BPD'];

    var MATRIX_TABLE   = 'x_birl3_clm_approval_matrix';
    var PAN_TABLE      = 'x_birl3_clm_nt_pan_request';
    var SITE_TABLE     = 'x_birl3_clm_nt_site_request';
    var CUSTOMER_TABLE = 'x_birl3_clm_clm_customer_master1';
    var SNAPSHOT_TABLE = 'x_birl3_clm_clm_aging_snapshot';
    var CG1 = 'N01';

    var F_NUMBER = 'number', F_APPROVAL = 'approval', F_DEVIATION = 'is_deviation', F_PAN = 'pan';
    var F_PREV_LIMIT = 'total_existing_limit', F_REQ_LIMIT = 'total_requested_limit', F_APP_LIMIT = 'total_approved_limit';
    var F_HISTORY = 'approval_history', F_CREATED_BY = 'sys_created_by', F_CREATED_ON = 'sys_created_on';
    var F_SITE_PAN = 'pan_request', F_SITE_CUST = 'customer_site_code';

    var F_CUST_NAME = 'customer_name', F_CUST_CODE = 'customer_code_sap', F_CUST_SEGMENT = 'segment';
    var F_CUST_ZONE = 'zone', F_CUST_ZONE_N = 'zone_name';
    var F_CUST_REGION = 'region', F_CUST_REGION_N = 'region_name';
    var F_CUST_DEPOT = 'depot', F_CUST_DEPOT_N = 'depot_name';

    var PERIOD_OPTIONS = [
        { label: 'All Time (Latest)', value: 'latest' },
        { label: 'This Year', value: 'current_year' },
        { label: 'Last Year', value: 'last_year' }
    ];
    var MAX_TABLE_ROWS = 500;
    var monthNames = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];

    // ---------------- helpers ----------------
    function pad(n) { return (n < 10 ? '0' : '') + n; }
    function norm(s) { return (s || '').toString().trim().toUpperCase().replace(/\s+/g, ' '); }
    function isTrue(v) { v = (v === null || v === undefined) ? '' : String(v).toLowerCase(); return v === '1' || v === 'true'; }
    function extractCode(val) {
        if (!val) return '';
        var m = String(val).match(/\(([^)]+)\)$/);
        return m ? m[1] : val;
    }
    function extractCodes(arr) {
        if (!arr || !Array.isArray(arr)) return [];
        return arr.map(extractCode).filter(function(x) { return x !== ''; });
    }
    function formatNameCode(name, code) {
        if (name && code && name !== code) return name + ' (' + code + ')';
        return name || code || '';
    }
    function normalizeArray(val) {
        if (typeof val === 'string') { try { val = JSON.parse(val); } catch (e) { val = val ? [val] : []; } }
        if (!Array.isArray(val)) val = val ? [val] : [];
        return val;
    }
    // Amount display in Indian units, picked by size:
    //   < 1,000            -> ₹950
    //   1,000 - 99,999     -> ₹1.5K
    //   1,00,000 - 99,99,999 -> ₹12.5L
    //   >= 1,00,00,000     -> ₹2.5Cr
    function formatAmt(v) {
        if (v === undefined || v === null || v === '') return '';
        var n = parseFloat(v);
        if (isNaN(n)) return v;

        var sign = n < 0 ? '-' : '';
        var a = Math.abs(n);
        var val, unit;

        if (a >= 10000000)      { val = a / 10000000; unit = 'Cr'; }
        else if (a >= 100000)   { val = a / 100000;   unit = 'L';  }
        else if (a >= 1000)     { val = a / 1000;     unit = 'K';  }
        else                    { val = a;            unit = '';   }

        // up to 2 decimals, trailing zeros removed (1.50 -> 1.5, 2.00 -> 2)
        var txt = String(parseFloat(val.toFixed(2)));
        return sign + '\u20B9' + txt + unit;
    }

	// Resolve sys_created_by (user name / email) to the user's full name
function buildUserNameMap(userNames) {
    var map = {}, list = [], seen = {};
    userNames.forEach(function(u) {
        u = String(u || '').trim();
        if (u && !seen[u.toLowerCase()]) { seen[u.toLowerCase()] = true; list.push(u); }
    });
    if (!list.length) return map;
    var ug = new GlideRecord('sys_user');
    var qu = ug.addQuery('user_name', 'IN', list.join(','));
    qu.addOrCondition('email', 'IN', list.join(','));
    ug.query();
    while (ug.next()) {
        var full = ug.getValue('name') || '';
        if (!full) continue;
        map[String(ug.getValue('user_name') || '').toLowerCase()] = full;
        map[String(ug.getValue('email') || '').toLowerCase()] = full;
    }
    return map;
}
function nameFromMap(map, raw) {
    raw = String(raw || '').trim();
    return map[raw.toLowerCase()] || raw;
}
    // Adjust here if your "approval" choice values differ
    function classify(val) {
        var s = (val || '').toString().toLowerCase();
        if (!s || s.indexOf('not') === 0 || s.indexOf('cancel') > -1) return '';
        if (s.indexOf('reject') > -1) return 'rejected';
        if (s.indexOf('approv') > -1) return 'approved';
        if (s.indexOf('request') > -1 || s.indexOf('pend') > -1 || s.indexOf('submit') > -1) return 'pending';
        return '';
    }
    // Latest approval_history journal entry -> person name only ("2026-10-28 10:15:00 - Name (label)")
    function historyName(gr) {
        var txt = '';
        try { txt = gr[F_HISTORY].getJournalEntry(1) + ''; }
        catch (e) { txt = (gr.getDisplayValue(F_HISTORY) || '') + ''; }
        if (!txt || txt === 'null' || txt === 'undefined') return '';
        var first = txt.split('\n')[0];
        first = first.replace(/^\d{4}-\d{2}-\d{2}\s+\d{2}:\d{2}:\d{2}\s*-\s*/, '');
        first = first.replace(/\s*\([^()]*\)\s*$/, '');
        return first.trim();
    }
    function segmentFromRole(role) {
        var r = norm(role);
        if (r.indexOf('CEMENT') > -1) return 'Cement';
        if (r.indexOf('RMC') > -1) return 'RMC';
        if (r.indexOf('BPD') > -1) return 'BPD';
        return '';
    }
    function setEmptyData() {
        data.filterOpts = { segments: [], zones: [], regions: [], depots: [], periods: PERIOD_OPTIONS };
        data.statusOptions = [];
        data.scorecards = { total: 0, pending: 0, approved: 0, rejected: 0, deviated: 0 };
        data.chart = { year: new Date().getFullYear(), months: [], monthKeys: [], rangeLabel: '', series: {}, max: 1 };
        data.requests = [];
        data.periodLabel = '';
    }

    data.requests = [];
    data.accessDenied = false; data.accessDeniedMsg = '';
    data.businessNotReady = false; data.businessNotReadyMsg = '';

    // ---------------- 1) Business options (CLMBusinessAccess, persona ZHM) ----------------
    function newAccess() {
        try { return new x_birl3_clm.CLMBusinessAccess(); } catch (e1) {}
        try { return new CLMBusinessAccess(); } catch (e2) {}
        return null;
    }
    var access = { trade: false, nonTrade: false, key: false };
    var ntRoles = NT_ROLES_FALLBACK;
    var accessObj = newAccess();
    if (accessObj) {
        try {
            var a = accessObj.getAccess(PERSONA) || {};
            access.trade = !!a.trade; access.nonTrade = !!a.nonTrade; access.key = !!a.key;
        } catch (e3) { gs.error('CLM NT ZHM approval requests: getAccess failed - ' + e3); }
        try { var rr = accessObj.RULES[PERSONA].nonTrade.roles; if (rr && rr.length) ntRoles = rr; } catch (e4) {}
    } else {
        gs.error('CLM NT ZHM approval requests: CLMBusinessAccess could not be created');
    }
    var allowedBiz = { trade: access.trade, non_trade: access.nonTrade, key: access.key };
    data.businessOptions = [];
    BUSINESS_ORDER.forEach(function(k) {
        if (allowedBiz[k] && BUSINESS_BUILT[k]) data.businessOptions.push({ value: k, label: BUSINESS_LABELS[k], enabled: true });
    });

    if (typeof input === 'undefined' || !input) {
        setEmptyData();
        data.initialLoad = true;
        data.selectedBusiness = DEFAULT_BUSINESS;
        data.businessLabel = BUSINESS_LABELS[DEFAULT_BUSINESS];
        return;
    }
    data.initialLoad = false;

    var inputFilters = input.filters ? input.filters : {};
    var selectedBusiness = (inputFilters.business || DEFAULT_BUSINESS).toString();
    if (!BUSINESS_LABELS[selectedBusiness]) selectedBusiness = DEFAULT_BUSINESS;
    data.selectedBusiness = selectedBusiness;
    data.businessLabel = BUSINESS_LABELS[selectedBusiness];

    if (selectedBusiness !== DEFAULT_BUSINESS) {
        setEmptyData();
        data.selectedPeriod = inputFilters.period || 'latest';
        data.businessNotReady = true;
        data.businessNotReadyMsg = selectedBusiness === 'key'
            ? 'Approval request details for Key customers are not available yet.'
            : 'Trade approval requests are shown in the Trade approval requests widget.';
        return;
    }

    // ---------------- 2) Approval-matrix scope (ZHM Non-Trade roles) ----------------
    var ntRolesNorm = ntRoles.map(norm);

    function tokenSet(gr, field) {
        var set = { __n: 0 };
        function add(v) { v = norm(v); if (v && !set[v]) { set[v] = true; set.__n++; } }
        [gr.getValue(field), gr.getDisplayValue(field)].forEach(function(raw) {
            if (!raw) return;
            String(raw).split(',').forEach(function(part) {
                part = part.trim();
                add(part); add(part.split('|')[0]); add(extractCode(part));
            });
        });
        return set;
    }

    var hasRows = false;
    var scopeRows = [];          // { segment:set, zone:set }
    var roleSegs = {};           // 'Cement' | 'RMC' | 'BPD'
    var assignedZoneRaw = [];    // zones typed on the matrix (to list them even if the master has none)

    var mx = new GlideRecord(MATRIX_TABLE);
    if (mx.isValid()) {
        mx.addQuery('approver_user', gs.getUserID());
        if (mx.isValidField('active')) mx.addQuery('active', true);
        mx.query();
        while (mx.next()) {
            var roleSet = {};
            [mx.getValue('role_name'), mx.getDisplayValue('role_name')].forEach(function(v) { if (v) roleSet[norm(v)] = true; });
            var matchedRole = ntRolesNorm.filter(function(r) { return roleSet[r]; })[0];
            if (!matchedRole) continue;
            var segLabel = segmentFromRole(matchedRole);
            if (!segLabel) continue;

            hasRows = true;
            roleSegs[segLabel] = true;
            var segSet = { __n: 1 }; segSet[norm(segLabel)] = true;

            var panIndia = isTrue(mx.getValue('pan_india'));
            var zoneSet = panIndia ? { __n: 0 } : tokenSet(mx, 'zone');
            if (!panIndia) {
                var rawZ = mx.getDisplayValue('zone') || mx.getValue('zone') || '';
                String(rawZ).split(',').forEach(function(p) { p = p.trim(); if (p && assignedZoneRaw.indexOf(p) === -1) assignedZoneRaw.push(p); });
            }
            scopeRows.push({ segment: segSet, zone: zoneSet });
        }
    }

    if (!hasRows) {
        setEmptyData();
        data.accessDenied = true;
        data.accessDeniedMsg = 'You are not assigned in the approval matrix with a Non-Trade zonal role (ZHM / ZCH), so there are no Non-Trade requests to show.';
        return;
    }

    function inSet(set, vals) {
        if (!set.__n) return true;
        for (var i = 0; i < vals.length; i++) if (vals[i] && set[norm(vals[i])]) return true;
        return false;
    }
    function inScope(cu) {
        for (var i = 0; i < scopeRows.length; i++) {
            var row = scopeRows[i];
            if (inSet(row.segment, [cu.segment]) && inSet(row.zone, [cu.zone, cu.zoneName])) return true;
        }
        return false;
    }

    // ---------------- 3) Filters ----------------
    inputFilters.segments = normalizeArray(inputFilters.segments);
    inputFilters.zones    = normalizeArray(inputFilters.zones);
    inputFilters.regions  = normalizeArray(inputFilters.regions);
    inputFilters.depots   = normalizeArray(inputFilters.depots);
    inputFilters.business = selectedBusiness;
    data.filters = inputFilters;

    var statusFilter = (inputFilters.status || '').toString();
    var period = inputFilters.period || 'latest';
    data.selectedPeriod = period;

    var allowedSegments = Object.keys(roleSegs).sort();
    var selSegNorm = inputFilters.segments.map(norm).filter(function(s) {
        return allowedSegments.some(function(a) { return norm(a) === s; });
    });
    var zoneCodes   = extractCodes(inputFilters.zones);
    var regionCodes = extractCodes(inputFilters.regions);
    var depotCodes  = extractCodes(inputFilters.depots);

    data.statusOptions = [
        { value: 'pending', label: 'Pending' }, { value: 'approved', label: 'Approved' }, { value: 'rejected', label: 'Rejected' }
    ];

    function passesFilters(cu) {
        if (selSegNorm.length && selSegNorm.indexOf(norm(cu.segment)) === -1) return false;
        if (zoneCodes.length   && zoneCodes.indexOf(cu.zone) === -1) return false;
        if (regionCodes.length && regionCodes.indexOf(cu.region) === -1) return false;
        if (depotCodes.length  && depotCodes.indexOf(cu.depot) === -1) return false;
        return true;
    }

    // ---------------- 4) Customer master (cg1 = N01) in scope -> dropdown options ----------------
    var masterRows = [];
    (function() {
        var ga = new GlideAggregate(CUSTOMER_TABLE);
        ga.addQuery('cg1', CG1);
        [F_CUST_SEGMENT, F_CUST_ZONE, F_CUST_ZONE_N, F_CUST_REGION, F_CUST_REGION_N, F_CUST_DEPOT, F_CUST_DEPOT_N]
            .forEach(function(f) { ga.groupBy(f); });
        ga.addAggregate('COUNT');
        ga.query();
        while (ga.next()) {
            var cu = {
                segment:    (ga.getDisplayValue(F_CUST_SEGMENT) || ga.getValue(F_CUST_SEGMENT) || '').split('|')[0].trim(),
                zone:       ga.getValue(F_CUST_ZONE) || '',
                zoneName:   ga.getValue(F_CUST_ZONE_N) || '',
                region:     ga.getValue(F_CUST_REGION) || '',
                regionName: ga.getValue(F_CUST_REGION_N) || '',
                depot:      ga.getValue(F_CUST_DEPOT) || '',
                depotName:  ga.getValue(F_CUST_DEPOT_N) || ''
            };
            if (inScope(cu)) masterRows.push(cu);
        }
    })();

    var zoneSet = {}, regionSet = {}, depotSet = {}, masterZoneKeys = {};
    masterRows.forEach(function(cu) {
        if (cu.zone) masterZoneKeys[norm(cu.zone)] = true;
        if (cu.zoneName) masterZoneKeys[norm(cu.zoneName)] = true;

        // Zone list: every zone in scope (not narrowed by the segment pick)
        var zl = formatNameCode(cu.zoneName, cu.zone);
        if (zl) zoneSet[zl] = true;

        var segOk  = !selSegNorm.length || selSegNorm.indexOf(norm(cu.segment)) > -1;
        var zoneOk = !zoneCodes.length || zoneCodes.indexOf(cu.zone) > -1;
        var regOk  = !regionCodes.length || regionCodes.indexOf(cu.region) > -1;
        if (segOk && zoneOk) { var rl = formatNameCode(cu.regionName, cu.region); if (rl) regionSet[rl] = true; }
        if (segOk && zoneOk && regOk) { var dl = formatNameCode(cu.depotName, cu.depot); if (dl) depotSet[dl] = true; }
    });
    // assigned zones that have no customer in the master are still listed
    assignedZoneRaw.forEach(function(z) {
        if (!masterZoneKeys[norm(z)] && !masterZoneKeys[norm(extractCode(z))]) zoneSet[z] = true;
    });

    data.filterOpts = {
        segments: allowedSegments,
        zones:    Object.keys(zoneSet).sort(),
        regions:  Object.keys(regionSet).sort(),
        depots:   Object.keys(depotSet).sort(),
        periods:  PERIOD_OPTIONS
    };

    // ---------------- 5) Period + chart window ----------------
    var nowGdt = new GlideDateTime();
    var nowStr = nowGdt.getValue();
    var curYear = parseInt(nowStr.substr(0, 4), 10), curMonth = parseInt(nowStr.substr(5, 2), 10), curDay = parseInt(nowStr.substr(8, 2), 10);

    var periodStart, periodEnd, periodLabel;
    if (period === 'current_year') {
        periodStart = curYear + '-01-01 00:00:00'; periodEnd = nowStr;
        periodLabel = 'Jan 1 – ' + monthNames[curMonth - 1] + ' ' + curDay + ', ' + curYear;
    } else if (period === 'last_year') {
        periodStart = (curYear - 1) + '-01-01 00:00:00'; periodEnd = (curYear - 1) + '-12-31 23:59:59';
        periodLabel = 'Jan 1 – Dec 31, ' + (curYear - 1);
    } else {
        periodStart = '1990-01-01 00:00:00'; periodEnd = nowStr; periodLabel = 'All Time (Latest)';
    }
    data.periodLabel = periodLabel;

    var nowLocalStr = nowGdt.getDisplayValueInternal();
    var curChartYear = parseInt(nowLocalStr.substr(0, 4), 10), curChartMonth = parseInt(nowLocalStr.substr(5, 2), 10);

    var monthKeys = [], monthLabels = [], monthIndex = {};
    var series = { total: [], pending: [], approved: [], rejected: [] };
    for (var back = 11; back >= 0; back--) {
        var cy = curChartYear, cm = curChartMonth - back;
        while (cm < 1) { cm += 12; cy--; }
        var mKey = cy + '-' + pad(cm);
        monthIndex[mKey] = monthKeys.length;
        monthKeys.push(mKey);
        monthLabels.push(monthNames[cm - 1] + " '" + String(cy).substr(2));
        series.total.push(0); series.pending.push(0); series.approved.push(0); series.rejected.push(0);
    }
    var chartStartGdt = new GlideDateTime();
    chartStartGdt.setDisplayValueInternal(monthKeys[0] + '-01 00:00:00');
    var chartStart = chartStartGdt.getValue();

    // ---------------- 6) PAN requests ----------------
    var qStart = periodStart < chartStart ? periodStart : chartStart;
    var qEnd   = periodEnd > nowStr ? periodEnd : nowStr;

    var pans = [];
    var panGr = new GlideRecord(PAN_TABLE);
    panGr.addQuery(F_CREATED_ON, '>=', qStart);
    panGr.addQuery(F_CREATED_ON, '<=', qEnd);
    panGr.orderByDesc(F_CREATED_ON);
    panGr.query();
    while (panGr.next()) {
        var cls = classify(panGr.getValue(F_APPROVAL));
        if (!cls) continue;
        pans.push({
            id: panGr.getUniqueValue(),
            cls: cls,
            dev: isTrue(panGr.getValue(F_DEVIATION)),
            pan: panGr.getDisplayValue(F_PAN) || '',      // NEW
            created: panGr.getValue(F_CREATED_ON) || ''
        });
    }

    // ---------------- 7) Site requests -> customers per PAN request ----------------
    function dw(gr, f) { return gr.getElement(F_SITE_CUST + '.' + f).toString() || ''; }
    function dwLabel(gr, f) { return gr.getElement(F_SITE_CUST + '.' + f).getDisplayValue() || ''; }

    function fetchSites(ids) {
        var map = {}, seen = {};
        for (var i = 0; i < ids.length; i += 250) {
            var gr = new GlideRecord(SITE_TABLE);
            gr.addQuery(F_SITE_PAN, 'IN', ids.slice(i, i + 250));
					  gr.orderByDesc('sys_created_on');   // latest site request first
            gr.query();
            while (gr.next()) {
                var pid = gr.getValue(F_SITE_PAN), cid = gr.getValue(F_SITE_CUST);
                if (!pid || !cid || seen[pid + '_' + cid]) continue;
                seen[pid + '_' + cid] = true;
                (map[pid] = map[pid] || []).push({
                    id: cid,
                    name: dw(gr, F_CUST_NAME) || gr.getDisplayValue(F_SITE_CUST),
                    code: dw(gr, F_CUST_CODE),
                    segment: (dwLabel(gr, F_CUST_SEGMENT) || dw(gr, F_CUST_SEGMENT)).split('|')[0].trim(),
                    zone: dw(gr, F_CUST_ZONE), zoneName: dw(gr, F_CUST_ZONE_N),
                    region: dw(gr, F_CUST_REGION), regionName: dw(gr, F_CUST_REGION_N),
                    depot: dw(gr, F_CUST_DEPOT), depotName: dw(gr, F_CUST_DEPOT_N)
                });
            }
        }
        return map;
    }

    var sitesMap = fetchSites(pans.map(function(p) { return p.id; }));
    var visible = pans.filter(function(p) {
        return (sitesMap[p.id] || []).some(function(cu) { return inScope(cu) && passesFilters(cu); });
    });

    // ---------------- 8) KPI tiles + chart ----------------
    var sc = { total: 0, pending: 0, approved: 0, rejected: 0, deviated: 0 };
    var maxVal = 1;
    visible.forEach(function(p) {
        if (p.created >= periodStart && p.created <= periodEnd) {
            sc[p.cls]++; sc.total++;
            if (p.dev) sc.deviated++;
        }
        if (p.created >= chartStart) {
            var local = new GlideDateTime(p.created).getDisplayValueInternal();
            var idx = monthIndex[local.substr(0, 7)];
            if (typeof idx !== 'undefined') { series[p.cls][idx]++; series.total[idx]++; }
        }
    });
    data.scorecards = sc;
    Object.keys(series).forEach(function(k) { series[k].forEach(function(v) { if (v > maxVal) maxVal = v; }); });
    var fk = monthKeys[0].split('-');
    data.chart = {
        year: curChartYear, monthKeys: monthKeys, months: monthLabels,
        rangeLabel: monthNames[parseInt(fk[1], 10) - 1] + ' ' + fk[0] + ' – ' + monthNames[curChartMonth - 1] + ' ' + curChartYear + ' (month to date)',
        series: series, max: maxVal
    };

    // ---------------- 9) Table rows ----------------
     // ---------------------------------------------------------------------------------
    // 10) Table rows
    // ---------------------------------------------------------------------------------
    var tableRows = visible.filter(function(p) {
        return p.created >= periodStart && p.created <= periodEnd && (!statusFilter || p.cls === statusFilter);
    }).slice(0, MAX_TABLE_ROWS);

    var tableIds = tableRows.map(function(p) { return p.id; });

    if (tableIds.length === 0) return;

    // ---- Pending approvers: sysapproval_approver where state = requested ----
    var pendingMap = {};   // PAN request sys_id -> [approver names]
    var pAppGr = new GlideRecord('sysapproval_approver');
    var pQc = pAppGr.addQuery('sysapproval', 'IN', tableIds);
    pQc.addOrCondition('document_id', 'IN', tableIds);
    pAppGr.addQuery('state', 'requested');
    pAppGr.orderBy('sys_created_on');
    pAppGr.query();
    while (pAppGr.next()) {
        var pReqId = pAppGr.getValue('sysapproval') || pAppGr.getValue('document_id');
        if (!pReqId) continue;
        var pName = pAppGr.getDisplayValue('approver') || pAppGr.getDisplayValue('group') || '';
        if (!pName) continue;
        var pList = pendingMap[pReqId] = pendingMap[pReqId] || [];
        if (pList.indexOf(pName) === -1) pList.push(pName);
    }

    if (!sitesMap) sitesMap = fetchSites(tableIds);

    // ---- Prev Limit: sum of cr_limit of ALL customers in customer master with the same PAN ----
    var panValues = [], panSeen = {};
    tableRows.forEach(function(p) {
        if (p.pan && !panSeen[p.pan]) { panSeen[p.pan] = true; panValues.push(p.pan); }
    });

    var panLimitMap = {};   // pan -> total cr_limit
    for (var pi = 0; pi < panValues.length; pi += 250) {
        var cGr = new GlideRecord(CUSTOMER_TABLE);
        cGr.addQuery('pan', 'IN', panValues.slice(pi, pi + 250).join(','));
        cGr.query();
        while (cGr.next()) {
            var cPan = cGr.getValue('pan') || '';
            var curCl = parseFloat(cGr.getValue('cr_limit') || cGr.getValue('credit_limit')) || 0;
            panLimitMap[cPan] = (panLimitMap[cPan] || 0) + curCl;
        }
    }

    var fin = new GlideRecord(PAN_TABLE);
    fin.addQuery('sys_id', 'IN', tableIds);
    fin.orderByDesc(F_CREATED_ON);
    fin.query();
    while (fin.next()) {
        var pid2 = fin.getUniqueValue();
        var st = classify(fin.getValue(F_APPROVAL));
        var sites = sitesMap[pid2] || [];
        var panVal = fin.getDisplayValue(F_PAN) || '';

        var latest = sites.filter(function(cu) { return inScope(cu) && passesFilters(cu); })[0] || sites[0];

        data.requests.push({
            business:      selectedBusiness,
            requestId:     pid2,
            requestCode:   fin.getDisplayValue(F_NUMBER) || pid2,
            pan:           panVal,
            customerNames: sites.map(function(cu) { return cu.name; }).join(' | '),
            customerCodes: sites.map(function(cu) { return cu.code; }).join(' | '),
            customerName:  latest ? latest.name : '',
            customerCode:  latest ? latest.code : '',
            status:        st,
            statusLabel:   st.charAt(0).toUpperCase() + st.slice(1),
            isDeviation:   isTrue(fin.getValue(F_DEVIATION)),
            stage:         st === 'pending' ? (pendingMap[pid2] || []).join(', ') : '',
            submittedBy:   fin.getValue(F_CREATED_BY),
            submittedOn:   fin.getDisplayValue(F_CREATED_ON),
            prevLimit:     formatAmt(panLimitMap[panVal] || 0),   // CHANGED: from customer master cr_limit
            requested:     formatAmt(fin.getValue(F_REQ_LIMIT)),
            approved:      formatAmt(fin.getValue(F_APP_LIMIT))
        });
    }

    // Submitted By: user name / email -> full name (one query)
    var ntUserMap = buildUserNameMap(data.requests.map(function(r) { return r.submittedBy; }));
    data.requests.forEach(function(r) { r.submittedBy = nameFromMap(ntUserMap, r.submittedBy); });

})();
